def t(language: str, key: str) -> str:
    """Get a static UI string, falling back to English if missing."""
    return UI_STRINGS.get(language, UI_STRINGS["English"]).get(key, UI_STRINGS["English"].get(key, key))


TRANSLATE_PROMPT = """Translate the given scam-analysis fields into {language}.
Use simple, everyday spoken {language} that anyone can understand, including
people with little formal education. Avoid formal, bureaucratic, or technical
words. Keep meanings exactly the same - do not add or remove warnings.
Reply with ONLY a JSON object with the same three keys: scam_type, indicators, recommendation."""


def translate_analysis(result: dict, language: str) -> dict:
    """Translate the dynamic parts of a quick_analyze() result. Returns the
    original result unchanged (safe fallback) if language is English or if
    translation fails for any reason - a failed translation must never break
    the analysis itself."""
    if language == "English" or language not in LANGUAGES:
        return result

    payload = {
        "scam_type": result.get("scam_type", ""),
        "indicators": result.get("indicators", []),
        "recommendation": result.get("recommendation", ""),
    }

    try:
        response = openai_client.responses.create(
            model=MODEL,
            input=[
                {"type": "message", "role": "system", "content": TRANSLATE_PROMPT.format(language=language)},
                {"type": "message", "role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
        )
        raw = response.output_text.strip()
        if raw.startswith("```"):
            raw = raw.strip("`")
            if raw.lower().startswith("json"):
                raw = raw[4:].strip()
        translated = json.loads(raw)

        merged = dict(result)
        merged["scam_type"] = translated.get("scam_type", result.get("scam_type"))
        merged["indicators"] = translated.get("indicators", result.get("indicators"))
        merged["recommendation"] = translated.get("recommendation", result.get("recommendation"))
        merged["_translated_to"] = language
        return merged
    except Exception:
        # Translation is a nice-to-have; never let it break the analysis itself.
        return result
